(window.TNQ=window.TNQ||[]).push({"terms":{"담세자":{"d":"세금을 실제로 부담하는 사람으로 세금을 납부하는 납세의무자와 다를 수 있습니다.","r":[]},"물납":{"d":"세금을 돈이 아닌 물건으로 대신 내는 것으로 특수한 경우에만 허용됩니다.","r":[]},"누진과세":{"d":"과세표준이 늘어날수록 더 높은 세율을 적용하는 과세 방식입니다.","r":[]},"열거주의":{"d":"과세 대상 소득을 법에 열거한 것으로 한정하는 방식으로 이자·배당만 유형별 포괄주의를 예외로 둡니다.","r":[]},"원천징수":{"d":"소득을 지급하는 자가 세금을 미리 떼어 대신 납부하는 제도입니다.","r":[]},"손금불산입":{"d":"법인세 계산에서 비용으로 인정하지 않아 소득에 더하는 세무조정입니다.","r":[]},"자본적 지출":{"d":"자산의 가치를 높이거나 내용연수를 늘리는 지출로 자산의 원가에 더합니다.","r":[]},"간주공급":{"d":"실제 공급이 아니지만 부가가치세법상 재화의 공급으로 보는 개인적공급, 사업상 증여 등을 말합니다.","r":[]},"하치장":{"d":"재화의 보관·관리 시설만 갖춘 장소로 설치신고를 하면 사업장으로 보지 않습니다.","r":[]}},"notes":{"1년을 2개의 과세기간으로 나누어, 매 6개월마다 확정신고 납부하도록 하고 있다":"일반과세자는 1년을 둘로 나눠 6개월마다 확정신고·납부합니다.","2025년: (손금불산입) 1,000,000원 (유보)":"이 사례는 2025년에 손금불산입 1,000,000원을 하고 유보로 처분하는 조정입니다.","2025년: (손금산입) 1,000,000원 (△유보)":"사례 1의 첫해에는 2025년에 손금산입 1,000,000원을 하고 △유보로 처분합니다.","2025년: (손금산입) 4,000,000원 (△유보)":"이 사례는 2025년에 손금산입 4,000,000원을 하고 △유보로 처분하는 조정입니다.","2026년: (손금산입) 2,000,000원 (△유보)":"이어 2026년에는 손금산입 2,000,000원이며 이것도 △유보입니다.","간주공급 중 개인적공급에 해당할 경우 세금계산서 발급의무가 면제된다":"개인적공급은 간주공급이라 세금계산서를 발급할 의무가 면제됩니다.","간주공급 중 면세전용의 공급시기는 재화를 사용하거나 소비하는 때이다":"면세전용은 재화를 사용하거나 소비하는 때가 공급시기입니다.","건물에 엘리베이터를 설치한 비용은 자본적 지출에 해당":"엘리베이터를 달아 건물 가치를 높이는 비용은 자본적 지출입니다.","계약상 의무불이행으로 인한 지체상금은 손금항목":"계약 의무를 어겨 물게 된 지체상금은 손금에 들어갑니다.","공공단체가 공공사업에 필요한 경비에 충당하기 위하여 부과하는 공과금은 조세에 해당하지 않는다":"공공사업 경비를 대려고 공공단체가 매기는 공과금은 조세가 아닙니다.","과세기간을 1월 1일부터 12월 31일로 한다":"간이과세자의 과세기간은 1월 1일부터 12월 31일까지입니다.","과세표준의 증가에 따라 세율이 증가하는 누진과세를 채택":"소득이 커질수록 세율도 올라가는 누진과세 방식입니다.","국내은행에서 발생하는 정기예금이자 1,500만원 외의 다른 소득이 없는 거주자 김철수 할아버지는 종합소득세 확정신고를 안 해도 된다":"이자소득이 1,500만원뿐인 거주자는 확정신고 없이 마칠 수 있다는 예입니다.","국세기본법에 따른 동일한 처분에 대하여 심사청구와 심판청구를 중복하여 제기할 수 없다":"같은 처분에 대해 심사청구와 심판청구를 겹쳐서 낼 수는 없습니다.","국세를 조사·결정할 때, 장부의 기록내용이 사실과 다르거나 장부의 기록에 누락된 것이 있을 때에는 그 부분에 대해서만 과세관청이 조사한 사실에 따라 결정할 수 있다":"장부가 사실과 다르거나 빠진 부분이 있으면 그 부분만 과세관청이 조사한 사실대로 결정할 수 있습니다.","그 부동산의 등기부상의 소재지를 사업장으로 한다":"부동산임대업은 부동산의 등기부상 소재지가 사업장입니다.","근로를 제공한 날이 속하는 사업연도":"인정상여는 근로를 제공한 날이 속한 사업연도에 소득이 생긴 것으로 봅니다.","납세의무자와 담세자가 다른 조세":"부가가치세는 세금을 내는 사람과 실제로 부담하는 사람이 다른 조세입니다.","납세자가 그 의무를 이행할 때 신의에 따라 성실하게 할 것을 요구하는 원칙으로, 세무공무원이 직무를 수행할 때에도 적용된다":"신의성실의 원칙은 납세자는 물론 세무공무원이 직무를 할 때도 신의에 따라 성실해야 한다는 뜻입니다.","납세자의 소득수준과 관계없이 모두 동일한 세율이 적용된다":"소득수준이 달라도 모든 납세자에게 같은 세율을 적용합니다.","내국법인의 부장으로 근무하는 김삼일씨가 근로소득 총수입금액 1억원 외의 다른 소득이 없는 경우 종합소득세 확정신고를 안 해도 된다":"근로소득 1억원 외에 다른 소득이 없으면 종합소득세 확정신고를 하지 않아도 되는 예입니다.","당해 법인의 잉여금 처분 결의일":"잉여금 처분에 의한 상여는 법인이 잉여금 처분을 결의한 날에 소득을 얻은 것으로 봅니다.","따로 사업연도를 정하여 법인 설립신고 또는 사업자등록과 함께 납세지 관할 세무서장에게 사업연도를 신고하여야 하며, 신고하지 않은 경우에는 매년 1월 1일부터 12월 31일까지를 그 법인의 사업연도로 한다":"규정이 없는 법인은 설립신고나 사업자등록 때 사업연도를 신고해야 하고, 신고하지 않으면 1월 1일부터 12월 31일까지로 봅니다.","무신고시 생산량비례법을 적용한다":"광업권은 상각방법을 신고하지 않으면 생산량비례법을 적용합니다.","법령이나 법인의 정관 등에서 정하는 1회계기간으로 하되 그 기간은 1년을 초과하지 못한다":"사업연도는 법령이나 정관이 정한 1회계기간으로, 1년을 넘길 수 없습니다.","법인의 업무에 직접 사용하지 않는 부동산은 업무무관자산에 해당":"업무에 직접 쓰지 않는 부동산이 업무무관자산입니다.","변경하려는 법인은 그 법인의 직전 사업연도 종료일부터 3개월 이내에 납세지 관할 세무서장에게 이를 신고하여야 한다":"사업연도를 바꾸려면 직전 사업연도 종료일부터 3개월 안에 관할 세무서장에게 신고합니다.","부가가치세 면세사업자의 총수입금액을 파악하기 위한 제도로써 다음연도 2월 10일까지 자진신고하여야 한다":"사업장 현황신고는 면세사업자의 수입을 파악하려는 제도로 다음연도 2월 10일까지 스스로 신고합니다.","사업을 위하여 무상으로 다른 사업자에게 인도 또는 양도하는 견본품은 사업상 증여에 해당하지 아니한다":"사업을 위해 무상으로 넘기는 견본품은 사업상 증여로 보지 않습니다.","세금을 실제로 부담하는 납세의무자와 이를 실제 신고 납부하는 원천징수의무자는 서로 다르다":"세금을 부담하는 사람과 신고·납부하는 원천징수의무자는 서로 다릅니다.","세무조사결과통지 또는 과세예고통지를 받은 자는 통지를 받은 날부터 30일 이내에 청구할 수 있다":"과세예고통지 등을 받은 사람은 통지받은 날부터 30일 안에 과세전적부심사를 청구할 수 있습니다.","수입자가 사업자인지 여부와 관계없이 부가가치세가 과세된다":"재화를 수입하면 수입자가 사업자인지와 상관없이 부가가치세가 부과됩니다.","실질과 다른 법형식을 통해 조세부담을 회피하는 행위를 방지하고 부담능력에 따른 과세를 실현하고자 하는 것":"법형식을 달리해 세금을 피하는 일을 막고 부담능력에 맞게 과세하려는 원칙입니다.","심판청구에 대한 결정통지를 받은 후 행정소송을 제기하려는 경우 심판청구에 대한 결정 통지를 받은 날부터 90일 이내에 제기하여야 한다":"심판청구 결정통지를 받은 날부터 90일 안에 행정소송을 내야 합니다.","업무무관부동산의 감가상각비는 손금불산입하여 유보로 소득처분한다":"업무무관부동산의 감가상각비는 비용으로 인정하지 않고 유보로 소득처분합니다.","원천징수로써 납세의무가 종결된다":"분리과세대상소득은 원천징수 하나로 납세의무가 끝납니다.","원칙적으로 열거주의에 의해 과세대상소득을 규정하고 있으며 예외적으로 이자 및 배당 소득에 한하여 유형별 포괄주의를 채택":"과세 대상 소득은 법에 열거한 것으로 한정하는 열거주의가 원칙이고, 이자·배당만 유형별 포괄주의를 예외로 씁니다.","재해로 손실되어 자산의 본래용도에 이용할 가치가 없는 건축물 등의 복구비용은 자본적 지출에 해당":"재해로 본래 용도에 쓸 수 없게 된 건축물의 복구비용도 자본적 지출입니다.","재화·용역을 공급하는 사업은 그 사업에 관한 업무총괄장소를 사업장으로 한다":"무인자동판매기로 하는 사업은 업무총괄장소가 사업장입니다.","재화의 보관 관리 시설만을 갖춘 장소로서 사업자가 관할세무서장에게 그 설치신고를 한 하치장은 사업장이 아니다":"보관·관리 시설만 있고 설치신고를 마친 하치장은 사업장이 아닙니다.","조세는 금전납부가 원칙이나, 특수한 경우 물납을 허용하고 있다":"돈으로 내는 것이 원칙이지만 특별한 경우에는 물건으로 내는 물납도 허용됩니다.","조세의 과세요건은 반드시 법률로 규정해야 한다":"세금을 매기는 요건은 법률로만 정할 수 있다는 조세법률주의가 바탕에 있습니다.","조세의 사용용도가 특정되지 않은 조세":"법인세는 쓰임새를 미리 정하지 않고 걷는 조세입니다.","최종소비자에게 이르기까지 모든 거래단계에서 창출된 부가가치에 대하여 각 단계별로 과세하는 다단계과세방법에 따르고 있다":"최종소비자에게 가는 모든 거래 단계에서 새로 생긴 부가가치에 단계마다 과세합니다.","퇴직소득과 양도소득은 다른 소득과 합산하지 않고 별도로 과세한다":"퇴직소득과 양도소득은 다른 소득과 합치지 않고 따로 과세하는 분류과세 대상입니다.","폐업일이 속하는 과세기간 개시일부터 폐업일까지를 최종 과세기간으로 한다":"폐업했다면 과세기간 개시일부터 폐업일까지가 마지막 과세기간입니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
